    val is_write_allowed: Boolean = false,
    val is_share_phone_number: Boolean = false,
    val vpeer: MTPInputPeer? = null,
    val vmsg_id: Int? = null,
    val vbutton_id: Int? = null,
    val vurl: String? = null,
    val vmatch_code: String? = null,
) : TlFunction<MTPUrlAuthResult> {
    override val constructorId: Int get() = CONSTRUCTOR
    override fun serializeBody(w: TlWriter) {
        w.int((if (is_write_allowed) 1 else 0) or (if (is_share_phone_number) 8 else 0) or (if (vpeer != null) 2 else 0) or (if (vmsg_id != null) 2 else 0) or (if (vbutton_id != null) 2 else 0) or (if (vurl != null) 4 else 0) or (if (vmatch_code != null) 16 else 0))
        vpeer?.let { it.serialize(w) }
        vmsg_id?.let { w.int(it) }
        vbutton_id?.let { w.int(it) }
        vurl?.let { w.string(it) }
        vmatch_code?.let { w.string(it) }
    }
    override fun parseResult(r: TlReader): MTPUrlAuthResult = r.obj() as MTPUrlAuthResult
    companion object {
        const val CONSTRUCTOR: Int = 0x67a3f0de.toInt()
    }
}

